-- TI-1037 / iMemories (aid 37423): per-3P-segment reach + overlap with iMemories' MM keyword layer.
-- 30-day window (3P/DS35 delivery is bursty ~2-4 load days/month -> never judge on <30d). Literal dt = partition prune.
WITH mm AS (  -- iMemories' MM (DS19) keyword universe = 211 keyword ids
  SELECT DISTINCT ip
  FROM `dw-main-bronze.external.ipdsc__v1`, UNNEST(data_source_category_ids.list) c
  WHERE dt BETWEEN '2026-05-24' AND '2026-06-22' AND data_source_id=19 AND c.element IN (900214,900315,900335,900517,900950,901097,901198,901548,901902,901947,901995,902218,902976,903173,903203,903457,903996,904127,904217,904292,904779,905620,905671,905908,906187,906546,906720,908124,908187,908262,908448,908651,908666,909312,909343,909614,909779,910402,910864,911217,911639,912007,912597,912627,912770,914364,914751,915871,915922,916090,916298,916314,916659,917091,917387,917405,917439,917673,918528,918577,918611,918633,918868,919340,919361,919417,920849,920878,920880,920980,921060,921141,922017,922497,922566,922638,922865,923161,923783,924222,924707,925270,925681,927083,927435,927689,927802,928094,928207,928306,928350,928466,928881,929217,929390,929970,931169,932082,932127,932185,932832,932969,933180,934069,934361,934709,934776,935501,936350,936388,936628,936817,937093,937662,937767,938458,938468,938768,939054,939070,939260,939748,939801,939841,940009,940144,940506,940735,941127,941218,941416,941597,942486,942604,942644,942912,943544,943563,943680,943699,944443,945133,945421,946152,946174,946255,947179,949393,949736,950370,950440,951166,951701,952728,953033,953623,953809,953869,955359,955599,956086,956244,956935,957433,957532,957654,957732,958263,958399,959122,959778,960507,960787,962084,963087,963273,963297,963761,964329,965464,965805,966032,966670,967492,968086,968674,968816,969144,969557,970226,970866,971348,971375,972341,972776,973176,973463,975345,975708,975964,975968,976676,976813,977176,977597,977857,978002,978284,978585,979140,979203)
),
tp AS (  -- iMemories' 3P (DS35) segments = 15 ids
  SELECT c.element AS cat, ip
  FROM `dw-main-bronze.external.ipdsc__v1`, UNNEST(data_source_category_ids.list) c
  WHERE dt BETWEEN '2026-05-24' AND '2026-06-22' AND data_source_id=35 AND c.element IN (1003536679,1004770179,1004788889,1008179391,1008486591,1009006961,1009010221,1011030701,1012012851,1012160271,1012917741,1013246001,1013279451,1014997731,1018194591)
)
SELECT s.cat AS data_source_category_id,
  COUNT(DISTINCT s.ip) AS reach_ips_30d,
  COUNT(DISTINCT IF(m.ip IS NOT NULL, s.ip, NULL)) AS ips_also_in_mm,
  ROUND(SAFE_DIVIDE(COUNT(DISTINCT IF(m.ip IS NOT NULL, s.ip, NULL)), COUNT(DISTINCT s.ip)),4) AS pct_overlap_with_mm
FROM tp s LEFT JOIN mm m ON s.ip=m.ip
GROUP BY s.cat ORDER BY reach_ips_30d DESC
